import stylesText from './status-screen.css?inline';
import { cssStyleSheet } from '../../utils/css.js';
import { goBack } from '../../router.js';

import '../status-pill/status-dot/status-dot.component.js';
import './sections/connectivity/connectivity-section.component.js';
import './sections/server/server-section.component.js';
import './sections/sync/sync-section.component.js';
import './sections/credential/credential-section.component.js';
import './sections/services/services-section.component.js';

import { type ServerSection } from './sections/server/server-section.component.js';
import { type SyncSection, type SyncState } from './sections/sync/sync-section.component.js';
import { type CredentialSection } from './sections/credential/credential-section.component.js';
import { createComponentLogger } from '../../utils/component-logger.js';
import {
    STATUS_EVENTS,
    type WakeEvent,
    type UnlockEvent,
    type BootEvent,
    type ShutdownEvent,
    type HardRebootEvent,
    type RefreshEvent,
    type SyncEvent,
    type DeleteOneEvent,
    type DeleteAllEvent,
    type DismissRejectedEvent,
    type SaveCredentialEvent,
    type ClearCredentialEvent,
} from './status-events.js';
import { dismissRejectedQueueEntry, getRejectedQueueEntries } from '../../services/offline/rejected-queue-entries.js';

import {
    bootStageOf,
    fetchServerStatus,
    isPiGatewayReachable,
    stageLabel,
    stageColor,
    wake,
    unlock,
    boot,
    shutdown,
    hardReboot,
    type ServerStatus,
    type BootStage,
    type ActionResult,
} from '../../services/server-control.service.js';
import {
    hasStoredCredential,
    storePassword,
    getPassword,
    clearCredential,
} from '../../services/server-credential.service.js';
import { SyncService, type PendingChange } from '../../services/sync/sync.service.js';
import type { ScreenComponent } from '../../types/screen-component.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
<header class="screen-header">
    <button class="back-btn" aria-label="Go back">←</button>
    <h1 class="screen-title">System Status</h1>
</header>
<main class="screen-body">
    <div class="section-container">
        <connectivity-status-section id="section-connectivity"></connectivity-status-section>
    </div>
    <div class="section-container">
        <server-status-section id="section-server"></server-status-section>
    </div>
    <div class="section-container">
        <sync-status-section id="section-sync"></sync-status-section>
    </div>
    
    <div class="feedback" id="feedback"></div>

    <div class="section-container">
        <credential-status-section id="section-credential"></credential-status-section>
    </div>
    <div class="section-container">
        <services-status-section id="section-services"></services-status-section>
    </div>
</main>
`;

function formatError(err: unknown): string {
    if (err instanceof Error) return `${err.name}: ${err.message}\n${err.stack ?? ''}`;
    return String(err);
}

export class StatusScreen extends HTMLElement implements ScreenComponent {
    setLoading(): void {}
    setError(err: unknown): void {}
    clearStatus(): void {}
    private readonly log = createComponentLogger('status-screen');
    private shadow: ShadowRoot;
    private feedbackEl!: HTMLDivElement;

    // Sections
    private sectionConnectivity!: HTMLElement;
    private sectionServer!: ServerSection;
    private sectionSync!: SyncSection;
    private sectionCredential!: CredentialSection;

    // State
    private isOnline = navigator.onLine;
    private serverStage: BootStage = 'unreachable';
    private serverStatus: ServerStatus | null = null;
    private syncState: SyncState = { count: 0, isSyncing: false, failedChange: null, error: null };
    private hasCredential = false;

    private polling: ReturnType<typeof setTimeout> | null = null;
    /** Story 380: the post-action refreshes and the feedback timer, cleared on disconnect. */
    private readonly timers = new Set<ReturnType<typeof setTimeout>>();
    private feedbackTimer: ReturnType<typeof setTimeout> | null = null;
    /** The error the last failed pending count put up, so a good count clears only its own. */
    private countError: string | null = null;

    private readonly onOnline = () => this.updateConnectivity(true);
    private readonly onOffline = () => this.updateConnectivity(false);

    constructor() {
        super();
        this.shadow = this.attachShadow({ mode: 'open' });
        this.shadow.adoptedStyleSheets = [styles];
        this.shadow.appendChild(template.content.cloneNode(true));
        // Story 380 (pwa-shell-04): the sections upgrade only after this screen's connectedCallback,
        // which sets their properties — an own property then shadowed each setter (the credential
        // section said "saved" and kept showing the input). Upgrade them now.
        customElements.upgrade(this.shadow);
    }

    connectedCallback() {
        this.feedbackEl = this.shadow.getElementById('feedback') as HTMLDivElement;

        this.sectionConnectivity = this.shadow.getElementById('section-connectivity') as HTMLElement;
        this.sectionServer = this.shadow.getElementById('section-server') as ServerSection;
        this.sectionSync = this.shadow.getElementById('section-sync') as SyncSection;
        this.sectionCredential = this.shadow.getElementById('section-credential') as CredentialSection;

        // Event Listeners
        this.shadow.querySelector('.back-btn')!.addEventListener('click', () => goBack('/'));

        window.addEventListener('online', this.onOnline);
        window.addEventListener('offline', this.onOffline);

        // Server Section Listeners
        this.sectionServer.addEventListener(STATUS_EVENTS.WAKE, (e: WakeEvent) => this.doWake());
        this.sectionServer.addEventListener(STATUS_EVENTS.UNLOCK, (e: UnlockEvent) => this.doUnlock());
        this.sectionServer.addEventListener(STATUS_EVENTS.BOOT, (e: BootEvent) => this.doBoot());
        this.sectionServer.addEventListener(STATUS_EVENTS.SHUTDOWN, (e: ShutdownEvent) => this.doShutdown());
        this.sectionServer.addEventListener(STATUS_EVENTS.HARD_REBOOT, (e: HardRebootEvent) => this.doHardReboot());
        this.sectionServer.addEventListener(STATUS_EVENTS.REFRESH, (e: RefreshEvent) => this.refreshServerStatus());

        // Sync Section Listeners
        this.sectionSync.addEventListener(STATUS_EVENTS.SYNC, (e: SyncEvent) => this.runSync());
        this.sectionSync.addEventListener(STATUS_EVENTS.DELETE_ONE, (e: DeleteOneEvent) => this.deletePendingChange(e.detail));
        this.sectionSync.addEventListener(STATUS_EVENTS.DELETE_ALL, (e: DeleteAllEvent) => this.deletePendingChangesFrom(e.detail));
        this.sectionSync.addEventListener(STATUS_EVENTS.DISMISS_REJECTED, (e: DismissRejectedEvent) => this.dismissRejected(e.detail));

        // Credential Section Listeners
        this.sectionCredential.addEventListener(STATUS_EVENTS.SAVE, (e: SaveCredentialEvent) => this.savePassword(e.detail));
        this.sectionCredential.addEventListener(STATUS_EVENTS.CLEAR, (e: ClearCredentialEvent) => this.clearPassword());

        // Story 307: the services section has no listeners — the Health Connect
        // sync it hosts is self-contained in `<hc-sync-panel>`.

        this.hasCredential = hasStoredCredential();
        this.sectionCredential.hasCredential = this.hasCredential;

        this.updateConnectivity(navigator.onLine);
        this.schedulePoll(0);
    }

    disconnectedCallback() {
        if (this.polling) clearTimeout(this.polling);
        for (const timer of this.timers) clearTimeout(timer);
        this.timers.clear();
        if (this.feedbackTimer) clearTimeout(this.feedbackTimer);
        window.removeEventListener('online', this.onOnline);
        window.removeEventListener('offline', this.onOffline);
    }

    // ── Polling ──────────────────────────────────────────────────────────────

    private schedulePoll(delayMs: number): void {
        if (this.polling) clearTimeout(this.polling);
        this.polling = setTimeout(() => void this.pollOnce(), delayMs);
    }

    private async pollOnce(): Promise<void> {
        await Promise.all([
            this.refreshServerStatus(),
            this.refreshSyncStatus()
        ]);
        // Story 380 (pwa-shell-03): removed while this was in flight — don't re-arm. (The backoff
        // this used to read was never counted; 30 s it is.)
        if (!this.isConnected) return;
        this.schedulePoll(30_000);
    }

    /** A refresh some seconds after an action, dropped if the screen is gone by then. */
    private refreshLater(delayMs: number): void {
        const timer = setTimeout(() => {
            this.timers.delete(timer);
            if (this.isConnected) void this.refreshServerStatus();
        }, delayMs);
        this.timers.add(timer);
    }

    // ── Connectivity ──────────────────────────────────────────────────────────

    private updateConnectivity(online: boolean) {
        this.isOnline = online;
        // The child component ConnectivitySection handles its own local render for online status via its own listeners, 
        // but it's good to keep this state in sync here if needed.
    }

    // ── Server Status ────────────────────────────────────────────────────────

    private async refreshServerStatus(): Promise<void> {
        const reachable = await isPiGatewayReachable();
        if (!reachable) {
            this.applyServerStage('unreachable', null);
            return;
        }
        const status = await fetchServerStatus().catch((err) => {
            this.log.error('fetchServerStatus failed:', err);
            return null;
        });
        if (!status) {
            this.applyServerStage('unreachable', null);
            return;
        }
        this.applyServerStage(await bootStageOf(status), status);
    }

    private applyServerStage(stage: BootStage, status: ServerStatus | null) {
        this.serverStage = stage;
        this.serverStatus = status;
        this.sectionServer.data = { stage, status };
    }

    // ── Sync Status ──────────────────────────────────────────────────────────

    private async refreshSyncStatus(): Promise<void> {
        try {
            const count = await SyncService.getPendingCount();
            this.syncState.count = count;
            // Story 380 (pwa-shell-14): a count that works again takes its own error down — but
            // not a sync's, which this would otherwise erase.
            if (this.countError !== null && this.syncState.error === this.countError) this.syncState.error = null;
            this.countError = null;
            this.updateSyncUI();
        } catch (err) {
            this.log.error('getPendingCount failed:', err);
            this.countError = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
            this.syncState.error = this.countError;
            this.updateSyncUI();
        }
        await this.refreshRejected();
    }

    /** Story 362: photos and estimates the server refused. Their own IndexedDB queues, so they load even when the replica cannot. */
    private async refreshRejected(): Promise<void> {
        try {
            this.syncState.rejected = await getRejectedQueueEntries();
        } catch (err) {
            this.log.error('getRejectedQueueEntries failed:', err);
            this.syncState.error = formatError(err);
        }
        this.updateSyncUI();
    }

    private async dismissRejected(entry: DismissRejectedEvent['detail']) {
        try {
            await dismissRejectedQueueEntry(entry);
        } catch (err) {
            this.log.error(`dismissRejectedQueueEntry(${entry.kind} ${entry.id}) failed:`, err);
            this.showFeedback(formatError(err), 'err');
        }
        await this.refreshRejected();
    }

    private updateSyncUI() {
        this.sectionSync.data = { ...this.syncState };
    }

    private async runSync() {
        if (this.syncState.isSyncing) return;
        this.syncState.isSyncing = true;
        this.syncState.error = null;
        this.syncState.failedChange = null;
        this.updateSyncUI();

        try {
            const result = await SyncService.syncPendingChanges();
            if (result.status === 'synced' || result.status === 'idle') {
                const quarantined = result.quarantined ?? [];
                if (quarantined.length > 0) {
                    // Story 267 — a change the server permanently rejected was
                    // dropped from the queue. Story 300's remainder adds two
                    // verdicts this client makes itself (a duplicate
                    // external_id, and a dependent whose parent was dropped), so
                    // the wording names the reasons rather than assuming the
                    // server gave them. It must never look like a clean sync:
                    // show it here (and it is in the log verbatim too).
                    const reasons = [...new Set(quarantined.map((entry) => entry.reason))].join(', ');
                    this.showFeedback(
                        `Synced ${result.applied} changes. QUARANTINED ${quarantined.length} change(s) — ${reasons} — not pushed, recorded in the client log:\n`
                        + JSON.stringify(quarantined, null, 2),
                        'err',
                    );
                } else {
                    this.showFeedback(`Synced ${result.applied} changes.`, 'ok');
                }
            } else {
                this.syncState.error = result.error;
                this.syncState.failedChange = result.failedChange ?? null;
                this.showFeedback('Sync encountered errors.', 'err');
            }
        } catch (err) {
            const raw = err instanceof Error ? `${err.name}: ${err.message}\n${err.stack ?? ''}` : String(err);
            this.syncState.error = raw;
            this.showFeedback(raw, 'err');
        } finally {
            this.syncState.isSyncing = false;
            await this.refreshSyncStatus();
            this.updateSyncUI();
        }
    }

    private async deletePendingChange(id: number) {
        try {
            await SyncService.deletePendingChange(id);
            this.showFeedback('Change deleted.', 'ok');
            this.syncState.failedChange = null;
            this.syncState.error = null;
            await this.refreshSyncStatus();
        } catch (err) {
            this.log.error(`deletePendingChange(${id}) failed:`, err);
            this.showFeedback(formatError(err), 'err');
        }
    }

    private async deletePendingChangesFrom(id: number) {
        try {
            await SyncService.deletePendingChangesFrom(id);
            this.showFeedback('Changes deleted.', 'ok');
            this.syncState.failedChange = null;
            this.syncState.error = null;
            await this.refreshSyncStatus();
        } catch (err) {
            this.log.error(`deletePendingChangesFrom(${id}) failed:`, err);
            this.showFeedback(formatError(err), 'err');
        }
    }

    // ── Health Connect bridge (story 250) ───────────────────────────────────
    //
    // Story 307: the sync moved into `<hc-sync-panel>`, which the services
    // section hosts and the day screen mounts too. It owns its own bridge
    // probe, cooldown and result — this screen no longer sits in the middle.

    // ── Credentials ──────────────────────────────────────────────────────────

    private savePassword(pw: string) {
        storePassword(pw);
        this.hasCredential = true;
        this.sectionCredential.hasCredential = true;
        this.showFeedback('Password saved for this session.', 'ok');
    }

    private clearPassword() {
        clearCredential();
        this.hasCredential = false;
        this.sectionCredential.hasCredential = false;
        this.showFeedback('Password cleared.', 'ok');
    }

    // ── UI Helpers ───────────────────────────────────────────────────────────

    private showFeedback(message: string, type: 'ok' | 'err') {
        this.feedbackEl.textContent = message;
        this.feedbackEl.className = `feedback feedback--visible feedback--${type}`;
        // Story 380 (pwa-shell-14): an earlier "ok" message's timer cleared whatever followed it,
        // so an error a second later vanished.
        if (this.feedbackTimer) clearTimeout(this.feedbackTimer);
        this.feedbackTimer = type === 'ok' ? setTimeout(() => this.clearFeedback(), 5000) : null;
    }

    private clearFeedback() {
        this.feedbackEl.textContent = '';
        this.feedbackEl.className = 'feedback';
    }

    // ── Server Actions Logic ──────────────────

    private async doWake() {
        const result = await wake().catch((e: Error) => {
            this.log.error('wake failed:', e);
            return { success: false, error: e.message } as ActionResult;
        });
        if (result.success) {
            this.showFeedback(result.message ?? 'WoL packet sent.', 'ok');
            this.refreshLater(8_000);
        } else {
            this.showFeedback(result.error ?? 'Wake failed.', 'err');
        }
    }

    private async doUnlock() {
        const pw = getPassword();
        if (!pw) { this.showFeedback('Enter master password first.', 'err'); return; }
        const result = await unlock(pw).catch((e: Error) => {
            this.log.error('unlock failed:', e);
            return { success: false, error: e.message } as ActionResult;
        });
        if (result.success) {
            this.showFeedback(result.message ?? 'Drive decrypted.', 'ok');
            this.refreshLater(5_000);
        } else {
            this.showFeedback(result.error ?? 'Unlock failed.', 'err');
        }
    }

    private async doBoot() {
        const pw = getPassword();
        if (!pw) { this.showFeedback('Enter master password first.', 'err'); return; }
        const result = await boot(pw).catch((e: Error) => {
            this.log.error('boot failed:', e);
            return { success: false, error: e.message } as ActionResult;
        });
        if (result.success) {
            this.showFeedback(result.message ?? 'Booting...', 'ok');
            this.refreshLater(10_000);
        } else {
            this.showFeedback(result.error ?? 'Boot failed.', 'err');
        }
    }

    private async doShutdown() {
        const pw = getPassword();
        if (!pw) { this.showFeedback('Enter master password first.', 'err'); return; }
        const result = await shutdown(pw).catch((e: Error) => {
            this.log.error('shutdown failed:', e);
            return { success: false, error: e.message } as ActionResult;
        });
        if (result.success) {
            this.showFeedback(result.message ?? 'Shutting down...', 'ok');
            this.refreshLater(8_000);
        } else {
            this.showFeedback(result.error ?? 'Shutdown failed.', 'err');
        }
    }

    private async doHardReboot() {
        const pw = getPassword();
        if (!pw) { this.showFeedback('Enter master password first.', 'err'); return; }
        if (!confirm('Force-reboot the server now? This is a hard reset (SysRq) for when it is wedged — only the last few seconds of unsynced writes are at risk.')) return;
        const result = await hardReboot(pw).catch((e: Error) => {
            this.log.error('hardReboot failed:', e);
            return { success: false, error: e.message } as ActionResult;
        });
        if (result.success) {
            this.showFeedback(result.message ?? 'Force reboot sent…', 'ok');
            this.refreshLater(30_000);
        } else {
            this.showFeedback(result.error ?? 'Force reboot failed.', 'err');
        }
    }
}

customElements.define('status-screen', StatusScreen);
