import '../../../health/hc-sync/hc-sync-panel.component.js';

const template = document.createElement('template');
template.innerHTML = `
    <div class="section">
        <div class="section-header">
            <h3 class="section-title">Connected Services</h3>
        </div>
        <hc-sync-panel id="hc"></hc-sync-panel>
    </div>
`;

/**
 * Health Connect bridge block (story 250 — replaced the Strava OAuth block).
 *
 * Story 307 moved the whole interaction — reachability, the sync call, the
 * result, the cooldown, the duplicate cards — into `<hc-sync-panel>`, so the
 * day screen can mount the same element instead of copying it. What is left
 * here is the section chrome around it, and the panel's own dot/badge is the
 * bridge indicator (the section header no longer carries a second one saying
 * the same thing).
 */
export class ServicesSection extends HTMLElement {
    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.appendChild(template.content.cloneNode(true));
    }
}

if (!customElements.get('services-status-section')) {
    customElements.define('services-status-section', ServicesSection);
}
