import type { ImageScope } from '../files.service.js';
import { deleteEstimateSubmit, getRejectedEstimateSubmits } from './estimate-submit-store.js';
import { deleteUpload, getRejectedUploads } from './image-upload-store.js';

/**
 * Story 362: what the offline queues set aside — a photo or estimate the server
 * refused for good (4xx but 408/429). Each one waits, with the server's words,
 * until the user dismisses it on the status screen. Story 267's quarantine is
 * the model.
 */
export interface RejectedQueueEntry {
    kind: 'photo' | 'estimate';
    id: string;
    label: string;
    reason: string;
}

const PHOTO_LABELS: Record<ImageScope, string> = {
    food: 'Food photo',
    meal: 'Meal cover',
    ai: 'Estimate photo',
};

export async function getRejectedQueueEntries(): Promise<RejectedQueueEntry[]> {
    const [photos, estimates] = await Promise.all([getRejectedUploads(), getRejectedEstimateSubmits()]);
    return [
        ...photos.map((photo): RejectedQueueEntry => ({
            kind: 'photo',
            id: photo.id,
            label: `${PHOTO_LABELS[photo.scope]} ${photo.filename}`,
            reason: photo.rejected_reason ?? '',
        })),
        ...estimates.map((estimate): RejectedQueueEntry => ({
            kind: 'estimate',
            id: estimate.id,
            label: `Estimate for ${estimate.meal_type} on ${estimate.date}${estimate.description ? ` — ${estimate.description}` : ''}`,
            reason: estimate.rejected_reason,
        })),
    ];
}

export async function dismissRejectedQueueEntry(entry: Pick<RejectedQueueEntry, 'kind' | 'id'>): Promise<void> {
    if (entry.kind === 'photo') await deleteUpload(entry.id);
    else await deleteEstimateSubmit(entry.id);
}
